    public double predict(double[] features) {
        if (features == null || features.length < 16) return 0.0;
        double sum = 0.0;
        for (DecisionTree tree : trees) {
            sum += tree.predict(features);
        }
        double pred = sum / trees.length;
        return Math.max(0.0, pred);
    }
